import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"权威书籍与标准目录调研","description":"","frontmatter":{},"headers":[],"relativePath":"research/books.md","filePath":"research/books.md","lastUpdated":1791593565000}`),a={name:`research/books.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="权威书籍与标准目录调研" tabindex="-1">权威书籍与标准目录调研 <a class="header-anchor" href="#权威书籍与标准目录调研" aria-label="Permalink to “权威书籍与标准目录调研”">​</a></h1><p>按书拆条目，逐本对照站内覆盖。&quot;已覆盖&quot;指站内有正文页，&quot;部分&quot;指站内有相邻篇目但口径或角度不同，&quot;缺口&quot;指没有对应页。逐条差异与处置见<a href="/hello-design-patterns/research/coverage">覆盖核对与差异表</a>。</p><h2 id="设计模式-gof-1994-s1" tabindex="-1">设计模式（GoF，1994）[S1] <a class="header-anchor" href="#设计模式-gof-1994-s1" aria-label="Permalink to “设计模式（GoF，1994）[S1]”">​</a></h2><p>23 个模式，创建型 5、结构型 7、行为型 11，是本仓的基准线。</p><table tabindex="0"><thead><tr><th>分类</th><th>模式</th><th>站内</th></tr></thead><tbody><tr><td>创建型（5）</td><td>抽象工厂、建造者、工厂方法、原型、单例</td><td>5/5 全部有页</td></tr><tr><td>结构型（7）</td><td>适配器、桥接、组合、装饰、外观、享元、代理</td><td>7/7 全部有页</td></tr><tr><td>行为型（11）</td><td>责任链、命令、解释器、迭代器、中介者、备忘录、观察者、状态、策略、模板方法、访问者</td><td>11/11 全部有页</td></tr></tbody></table><p>GoF 之外，站内还收了它没有的条目：多例、对象池、服务定位器（创建型），动态代理、保护代理、远程代理、虚拟代理、智能指针、双向桥接、依赖注入（结构型），回调、DSL、快照（行为型），以及并发与特定领域两个目录。</p><h2 id="head-first-设计模式-第-2-版-2020-s2" tabindex="-1">Head First 设计模式（第 2 版，2020）[S2] <a class="header-anchor" href="#head-first-设计模式-第-2-版-2020-s2" aria-label="Permalink to “Head First 设计模式（第 2 版，2020）[S2]”">​</a></h2><p>案例书，模式比 GoF 少但讲解顺序按&quot;先解决一个问题&quot;排。它的目录全部落在站内已有的策略、观察者、命令、适配器与外观、模板方法、迭代器与组合、状态、单例、装饰、工厂方法、抽象工厂、代理这些篇里。</p><p>这本书给本仓带来两个额外要求：</p><ol><li>它在观察者一章讲开闭原则，第 2 版还加了 Lambda 与函数式接口的写法。站内没有专门讲开闭原则与 SOLID 的篇目，本次补在<a href="/hello-design-patterns/evolution/overview">现代演进导读</a>下的<a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a>。</li><li>它明确讨论单例的代价（全局状态、测试困难、序列化与反射破坏），站内<a href="/hello-design-patterns/creational/singleton">单例模式</a>有实现细节，缺反面视角，由<a href="/hello-design-patterns/anti-patterns/god-object">神对象</a>与<a href="/hello-design-patterns/anti-patterns/golden-hammer">金锤子</a>承接。</li></ol><h2 id="架构整洁之道-clean-architecture-2017-s3" tabindex="-1">架构整洁之道（Clean Architecture，2017）[S3] <a class="header-anchor" href="#架构整洁之道-clean-architecture-2017-s3" aria-label="Permalink to “架构整洁之道（Clean Architecture，2017）[S3]”">​</a></h2><p>三块内容与站内对应关系：</p><ul><li>SOLID 五原则 → 本次新增<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>与<a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a>；</li><li>依赖规则与层级划分（实体、用例、接口适配器、框架与驱动）→ 站内没有架构分层篇，本次不展开，只在 SOLID 篇里讲依赖方向；</li><li>组件级三原则（复用与使用等价、稳定依赖、无环依赖）→ 同上，列在 SOLID 篇的延伸阅读里，暂不单独成篇。</li></ul><p>SOLID 的更早出处是 Martin 2002 年那本书 [S4]，两本口径一致。</p><h2 id="企业应用架构模式-p-of-eaa-2002-s5" tabindex="-1">企业应用架构模式（P of EAA，2002）[S5] <a class="header-anchor" href="#企业应用架构模式-p-of-eaa-2002-s5" aria-label="Permalink to “企业应用架构模式（P of EAA，2002）[S5]”">​</a></h2><p>这本书的目录分领域逻辑、数据源架构、Web 表现层、分布、并发与事务几组。逐项核对：</p><ul><li>领域逻辑四式（事务脚本、领域模型、表模块、活动记录）：站内只有<a href="/hello-design-patterns/other/orm">ORM</a>里顺带提到活动记录与数据映射器，事务脚本在<a href="/hello-design-patterns/introduction">设计模式概览</a>里列了但没有页。本次新增<a href="/hello-design-patterns/other/transaction-script">事务脚本</a>，并与<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>对照。</li><li>数据源四式（表网关、行数据网关、活动记录、数据映射器）：由 ORM 篇覆盖，不单独成篇。</li><li>仓储与单元工作：站内原本没有，仓储与 DDD 的仓储同源 [S11]，本次不新增，列在差异表&quot;暂不收录&quot;，理由是与 ORM 篇的边界要先划清（已于 2026-10-10 补成<a href="/hello-design-patterns/other/repository">仓储与单元工作</a>）。</li><li>Web 表现层（前端控制器、页面控制器、模板视图）：MVC 篇部分覆盖，前端控制器缺，本次不新增。</li><li>远程外观与数据传输对象：与站内<a href="/hello-design-patterns/structural/remote-proxy">远程代理</a>角度不同，前者面向服务边界，后者面向对象访问，本次不新增，记入差异表（已于 2026-10-10 补成<a href="/hello-design-patterns/structural/remote-facade">远程外观与数据传输对象</a>）。</li></ul><h2 id="重构-第-2-版-2018-s6" tabindex="-1">重构（第 2 版，2018）[S6] <a class="header-anchor" href="#重构-第-2-版-2018-s6" aria-label="Permalink to “重构（第 2 版，2018）[S6]”">​</a></h2><p>坏味道目录（过长函数、过大的类、依恋情节、数据泥团、霰弹式修改等）是反模式篇的代码层依据。站内原本一条坏味道都没有，本次用<a href="/hello-design-patterns/anti-patterns/overview">反模式导读</a>把&quot;坏味道—反模式—模式&quot;三层关系讲清，具体坏味道的演进路径引 Joshua Kerievky 的《Refactoring to Patterns》[S14]，站内不逐条复制原书目录。</p><h2 id="antipatterns-1998-与-big-ball-of-mud-1997-s7-s8" tabindex="-1">AntiPatterns（1998）与 Big Ball of Mud（1997）[S7][S8] <a class="header-anchor" href="#antipatterns-1998-与-big-ball-of-mud-1997-s7-s8" aria-label="Permalink to “AntiPatterns（1998）与 Big Ball of Mud（1997）[S7][S8]”">​</a></h2><p>两份反模式来源，本次落到 4 篇正文：</p><table tabindex="0"><thead><tr><th>条目</th><th>出处</th><th>站内</th></tr></thead><tbody><tr><td>意面代码（Spaghetti Code）</td><td>AntiPatterns 架构类反模式 [S7]</td><td>新增</td></tr><tr><td>金锤子（Golden Hammer）</td><td>AntiPatterns 常用反模式 [S7]</td><td>新增</td></tr><tr><td>神对象（God Object）</td><td>词条与坏味道综合 [S25][S6]</td><td>新增</td></tr><tr><td>大泥球（Big Ball of Mud）</td><td>PLoP 论文 [S8]</td><td>新增</td></tr></tbody></table><p><a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a> 来自 Martin 的 bliki 条目 [S26]，与事务脚本配对讲。</p><h2 id="面向模式的软件架构-posa-卷-1-与卷-2-s9" tabindex="-1">面向模式的软件架构（POSA，卷 1 与卷 2）[S9] <a class="header-anchor" href="#面向模式的软件架构-posa-卷-1-与卷-2-s9" aria-label="Permalink to “面向模式的软件架构（POSA，卷 1 与卷 2）[S9]”">​</a></h2><ul><li>卷 1 的分层、管道-过滤器、黑板、代理：站内有<a href="/hello-design-patterns/structural/proxy">代理</a>；分层、管道-过滤器、黑板属约束全系统拓扑的架构风格，2026-10-10 已按判据定为不收录，处置记于<a href="/hello-design-patterns/research/coverage">差异表</a>。</li><li>卷 2 的反应器、主动器、主动对象、生产者-消费者、半同步/半异步：站内前四条都有页，半同步/半异步与<a href="/hello-design-patterns/concurrency/active-object">主动对象</a>接近，本次不新增。</li></ul><h2 id="企业集成模式-eip-2002-s10" tabindex="-1">企业集成模式（EIP，2002）[S10] <a class="header-anchor" href="#企业集成模式-eip-2002-s10" aria-label="Permalink to “企业集成模式（EIP，2002）[S10]”">​</a></h2><p>消息通道、消息路由器、消息转换器、发布订阅等条目，站内由<a href="/hello-design-patterns/behavioral/observer">观察者</a>、<a href="/hello-design-patterns/behavioral/mediator">中介者</a>、<a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链</a>覆盖了&quot;通知与分发&quot;的近似场景，但缺少消息管道与路由的独立篇目。本次不新增，记入差异表，理由是需要先决定本仓是否开&quot;集成模式&quot;分区（分区已于 2026-10-10 开出，四条各成一篇，见<a href="/hello-design-patterns/integration/overview">集成模式导读</a>）。</p><h2 id="领域驱动设计-ddd-2003-s11" tabindex="-1">领域驱动设计（DDD，2003）[S11] <a class="header-anchor" href="#领域驱动设计-ddd-2003-s11" aria-label="Permalink to “领域驱动设计（DDD，2003）[S11]”">​</a></h2><p>聚合、仓储、规格、限界上下文：站内原本一条都没有。仓储已于 2026-10-10 补成<a href="/hello-design-patterns/other/repository">仓储与单元工作</a>，规格仍暂不单独成篇；聚合与限界上下文属于战略设计，不在本仓&quot;模式&quot;口径内，两者都记入差异表&quot;暂不收录&quot;并写明理由。</p><h2 id="release-it-第-2-版-2018-s12" tabindex="-1">Release It!（第 2 版，2018）[S12] <a class="header-anchor" href="#release-it-第-2-版-2018-s12" aria-label="Permalink to “Release It!（第 2 版，2018）[S12]”">​</a></h2><p>稳定性模式中，站内一条都没有。熔断器应用面最广（限流、降级、故障隔离三个场景都用它），本次新增<a href="/hello-design-patterns/evolution/circuit-breaker">熔断器</a>。隔舱、超时、重试三条已于 2026-10-10 同批补齐；稳态是容量与降级的运维纪律，不单独成篇，处置见差异表 2c。</p><h2 id="微服务与容器-s13-s15" tabindex="-1">微服务与容器 [S13][S15] <a class="header-anchor" href="#微服务与容器-s13-s15" aria-label="Permalink to “微服务与容器 [S13][S15]”">​</a></h2><p>API 网关、服务发现、Saga、断路器 vs 熔断、Sidecar、声明式 API：站内只有<a href="/hello-design-patterns/other/event-sourcing">事件溯源</a>与 Saga 相关的叙述。这两本书的目录作为后续选题来源记录在差异表，本次不新增。</p><h2 id="本次按书籍目录得出的缺口" tabindex="-1">本次按书籍目录得出的缺口 <a class="header-anchor" href="#本次按书籍目录得出的缺口" aria-label="Permalink to “本次按书籍目录得出的缺口”">​</a></h2><p>共 14 项，全部补成新篇，逐项见<a href="/hello-design-patterns/research/coverage">覆盖核对与差异表</a>第二张表：</p><ul><li>反模式 6 篇：导读、神对象、大泥球、金锤子、意面代码、贫血模型。</li><li>现代演进 4 篇：导读、组合式设计、SOLID 与依赖规则、熔断器。</li><li>并发 3 篇：线程池、读写锁、工作窃取（<a href="/hello-design-patterns/introduction">设计模式概览</a>已声明，站内缺页）。</li><li>其他 1 篇：事务脚本（同为概览已声明缺页）。</li></ul>`,36)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};